  const ids=new Set(rows.map(e=>e.id));for(const id of ids)if(rows.some(e=>e.id===id&&e.amount>0)&&rows.some(e=>e.id===id&&e.amount<0))notes.push(effects[id].name+': opposing properties balanced each other.');
