 const BMCraftAudio={cue(){},result(){},activity(){},cooking(){return '';}},document={getElementById(){return null;}},chatLog=[];let lastChatTime=0;
 const Dungeon={memory,stat:body.stat,spellsLearned:{},requestSave:save,saveGame:save,updateSkills(){},getEffectiveDice(i){const [numDice,diceSides,flatMod]=SUNCAT_COMBAT.dice(i);return {numDice,diceSides,flatMod:flatMod+BMCraftMastery.bonus(i,Dungeon)};}};
