  function recipesFor(kind){const learned=BMFieldCraft.known();return Object.entries(recipes).filter(([id,r])=>r.kind===kind&&learned[id]===true);}
  function food(key){return recipesFor('cooking').find(([,r])=>Object.hasOwn(r.req,key));}
