      for(const e of i.craftData.effects){if(!material().effects[e.id])continue;if(e.start>0&&(e.id==='ward'||e.id==='poison'&&e.amount<0)){s.activeBuffs.push({name:i.name,type:'item_buff',craftGroup:group,craftInstant:true,craftProperty:e.id,amount:e.amount,startsAt:now+e.start*1000,expiresAt:now+(e.start+e.duration)*1000});continue;}if(e.id==='ward')s.currentWardTime=Math.max(0,Math.min(s.maxWards*3,s.currentWardTime+e.amount*3));else if(e.id==='poison'&&e.amount<0)s.activeBuffs=s.activeBuffs.filter(b=>b.name!=='Poison'&&b.craftProperty!=='poison');else{s.activeBuffs.push({name:i.name,type:['poison','burn'].includes(e.id)?'debuff':'item_buff',craftGroup:group,buffStat:({str:0,con:1,int:2,agi:3})[e.id],amount:e.amount,craftProperty:e.id,startsAt:now+(e.start||0)*1000,expiresAt:now+((e.start||0)+e.duration)*1000});}}
