      if(!resisted){const prior=s.activeBuffs.find(b=>b.source==='tavern_beer'&&b.expiresAt>now);if(prior)prior.expiresAt=now+Math.min(120000,prior.expiresAt-now+60000);else s.activeBuffs.push({name:'Drunk',source:'tavern_beer',type:'debuff',expiresAt:now+60000});}
