                const score=terms.filter(t=>!['map','card','npc','the','a','of'].includes(t)).reduce((sum,t)=>sum+(name.includes(t)?5:body.includes(t)?1:0),0)+(requestedId&&Number(requestedId)===Number(v.id??v.npcIndex)?100:0);
