    async function auditProfileAssumptions(playerId) {
            const player = players[playerId];
            if (!player || !player.playerProfile || !player.searchableMemories || player.searchableMemories.length === 0) return;

            let assumptionString = player.playerProfile.personality;
            if (!assumptionString || assumptionString === "Unknown") return;

            try {
                let assumptionVector = await createMemoryVector(assumptionString);
                let maxSimilarity = 0;
                
                // THE FIX: Look for the single strongest piece of evidence, rather than the average!
                for (let mem of player.searchableMemories) {
                    if (mem.vector) {
                        let score = cosineSimilarity(assumptionVector, mem.vector);
                        if (score > maxSimilarity) maxSimilarity = score;
                    }
                }

                // If literally nothing in their history justifies this trait
                if (maxSimilarity < 0.40) {
                    player.pendingVerification = `[EPISTEMIC AUDIT]: Your profile states: "${assumptionString}". However, your vector data shows no historical evidence for this. Subtly test the user to verify or falsify this trait.`;
                } else {
                    player.pendingVerification = null; 
                }
            } catch (e) {
                console.error("Audit Processing Error:", e);
            }
        }
    async function consolidateMemories(playerId, force = false) {
        const player = players[playerId];
        if (!player || playerId === SUNCAT_ID || !player.persistentId ||
            player.narrationEnabled === false || player.isConsolidating || isBankrupt()) return;
        const now = Date.now();
        if (now < (player._chapterRetryAt || 0)) return;
        const pending = pendingJournalMemories(player);
        if (!pending.length) return;
        const proseSignature=JOURNAL_PROSE.signature(getChapterSourceText(pending));
        if(player._chapterProseWait===proseSignature)return;
        const oldestAt = Date.parse(pending[0].timestamp) || now;
        const events = pending.reduce((n,m) => n +
            (m.sourceEvents?.filter(journalIsSource).length || 1), 0);
        if (!force && (now < (player._chapterNextAt || 0) ||
            (pending.length < 3 && events < 12 && now - oldestAt < JOURNAL_POLICY.maxWaitMs))) return;
        const batch = journalBatch(pending, m => getChapterSourceText([m]), force ? 24 : 12, force ? 48000 : 36000);
        const memories = player.searchableMemories;
        player._journalCanRecover=false;
        player.isConsolidating = true;
        console.log(`[Journal] Chapter started for ${player.name}: ${batch.length} source records.`);
        try {
            const model = genAI.getGenerativeModel({
                model: 'gemini-2.5-flash-lite',
                generationConfig: {maxOutputTokens: 4096, temperature: 0.65}
            });
            const prompt = buildJournalChapterPrompt(player.name,
                getPlayerChapterContinuity(player, batch), getChapterSourceText(batch), force);
            const prose = await JOURNAL_PROSE.draft({prompt, manual: force,
                previous:player.searchableMemories.filter(m=>m.isCore&&m.text).slice(-8).map(m=>m.text),source:getChapterSourceText(batch),
                generate:async text=>{const result=await journalDeadline(model.generateContent(text));if(result.response.usageMetadata)updateBudget(result.response.usageMetadata,playerId);return journalResponse(result);}});
            if (players[playerId] !== player || player.searchableMemories !== memories) return;
            const chapter = await appendPlayerChapter(playerId, player, prose, batch);
            if (!chapter) return;
            player._chapterRetryAt = 0;
            player._chapterProseWait=null;
            player._chapterError = '';
            player._journalError = player._digestError || '';
            console.log(`[Journal] ${chapter.title} saved for ${player.name}.`);
        } catch (error) {
            if(error.code==='JOURNAL_PROSE_RETRY')player._chapterProseWait=proseSignature;
            player._chapterRetryAt = error.code==='JOURNAL_PROSE_RETRY'?0:Date.now()+JOURNAL_POLICY.retryMs;
            player._chapterError = error.message;
            player._journalError = error.message;
            persistPlayerJournal(player);
            console.error('[Journal] Chapter failed; sources remain pending:', error.message);
        } finally { player.isConsolidating = false; }
    }
