       // --- 5. UNIFIED NEURAL EXECUTION (The ReAct Agent) ---
        
      

        // Grab the player's existing chat history
        let currentHistory =
            triggerType === "chat" && chatSessions[socketId]
                ? await chatSessions[socketId].getHistory()
                : [];

