            const activeToolDecls = getActiveTools(data.text, triggerType, playerFavor).filter(t=>!oracleOnly||['consultGameManual','searchPlayerMemories'].includes(t.name)||SUNCAT_MERCY.recognizes(data.text)&&SUNCAT_TOOL_GROUPS.combat.includes(t.name));
            
