/* Monster-free arrival room shared by generation, respawn and expeditions. */
const BMServerRefuge=(()=>{
 const contains=(r,x,y)=>!!r&&x>=r.left&&x<r.right+1&&y>=r.top&&y<r.bottom+1;
 function build(grid,town,floor=0){const x=town.x,y=town.y,r={left:x-2,right:x+2,top:y+3,bottom:y+7,door:{x:x+.5,y:y+3.5},spawn:{x:x+.5,y:y+5.5},exit:{x:x+1.5,y:y+5.5},version:1};
  for(let yy=r.top;yy<=r.bottom;yy++)for(let xx=r.left;xx<=r.right;xx++)grid[yy][xx]=(xx===r.left||xx===r.right||yy===r.top||yy===r.bottom)?25:floor;
  grid[Math.floor(r.door.y)][Math.floor(r.door.x)]=2;return r;
 }
 const inside=p=>p?.mapID===999&&contains(activeCustomMap?.safeRoom,p.x,p.y);
 return {contains,build,inside};
})();

