 const timer=setInterval(()=>{for(const r of rooms.values())if(Date.now()-r.createdAt>7200000||r.resultAt&&Date.now()-r.resultAt>120000||r.players.some(p=>!p.context&&Date.now()-p.disconnectedAt>60000))end(r,'The match has ended.');},5000);timer.unref?.();
